const plain=x=>x&&typeof x.get==='function'?x.get({plain:true}):x;const milli=v=>{const[w,f='']=String(v).split('.');return BigInt(w||'0')*1000n+BigInt(f.padEnd(3,'0').slice(0,3)||'0');};const decimal=v=>{const n=v<0n?-v:v;return(v<0n?'-':'')+(n/1000n)+'.'+String(n%1000n).padStart(3,'0');};const roundedRial=(q,p)=>(q*BigInt(p)+500n)/1000n;const invoiceTypes=['PURCHASE_INVOICE','SALES_INVOICE'];
