async function nextDocumentNumber(type,prefix,fiscalYear,transaction){await sequelize.query('INSERT IGNORE INTO commercial_document_number_sequences (document_type, fiscal_year, last_number, created_at, updated_at) VALUES (:type, :year, 0, NOW(), NOW())',{replacements:{type,year:fiscalYear},transaction});await sequelize.query('UPDATE commercial_document_number_sequences SET last_number = last_number + 1, updated_at = NOW() WHERE document_type = :type AND fiscal_year = :year',{replacements:{type,year:fiscalYear},transaction});const [rows]=await sequelize.query('SELECT last_number FROM commercial_document_number_sequences WHERE document_type = :type AND fiscal_year = :year',{replacements:{type,year:fiscalYear},transaction});return `${prefix}-${String(rows[0].last_number).padStart(6,'0')}`;}
async function lockDoc(id,t){return repo.CommercialDocument.findByPk(id,{transaction:t,lock:t.LOCK.UPDATE});}
async function lockPartner(id,type,t){const p=await repo.CommercialPartner.findByPk(id,{transaction:t,lock:t.LOCK.UPDATE});const expected=type.startsWith('PURCHASE')?'SUPPLIER':'CUSTOMER';if(!p||Number(p.is_active)!==1)throw ErrorApi.notFound('طرف‌حساب فعال پیدا نشد');if(p.partner_type!==expected&&p.partner_type!=='BOTH')throw ErrorApi.badRequest('نوع طرف‌حساب با سند همخوانی ندارد');return p;}
async function lockSalesRepresentative(id,t){if(!id)return null;const rep=await repo.SalesRepresentative.findByPk(id,{transaction:t,lock:t.LOCK.UPDATE});if(!rep||Number(rep.is_active)!==1)throw ErrorApi.notFound('ویزیتور فعال پیدا نشد');return rep;}
async function lockSalesRepresentativeForUpdate(id,currentId,t){if(!id)return null;const rep=await repo.SalesRepresentative.findByPk(id,{transaction:t,lock:t.LOCK.UPDATE});if(!rep||(Number(rep.is_active)!==1&&id!==currentId))throw ErrorApi.notFound('ویزیتور فعال پیدا نشد');return rep;}
async function lockProducts(items,t){const products=new Map();for(const id of [...new Set(items.map(x=>x.productId))].sort()){const p=await repo.Product.findByPk(id,{transaction:t,lock:t.LOCK.UPDATE});if(!p||Number(p.is_active)!==1)throw ErrorApi.notFound('محصول فعال پیدا نشد',{productId:id});products.set(id,p);}return products;}
async function lockSalesReturnProducts(partnerId,items,t){for(const productId of [...new Set(items.map(x=>x.productId||x.product_id))].sort()){await sequelize.query('INSERT INTO commercial_sales_return_quantity_locks (partner_id, product_id, created_at, updated_at) VALUES (:partnerId, :productId, NOW(), NOW()) ON DUPLICATE KEY UPDATE updated_at = VALUES(updated_at)',{replacements:{partnerId,productId},transaction:t});await sequelize.query('SELECT partner_id FROM commercial_sales_return_quantity_locks WHERE partner_id = :partnerId AND product_id = :productId FOR UPDATE',{replacements:{partnerId,productId},transaction:t});}}
async function lockWarehouse(id,t){const w=await repo.Warehouse.findByPk(id,{transaction:t,lock:t.LOCK.UPDATE});if(!w||Number(w.is_active)!==1)throw ErrorApi.notFound('انبار فعال پیدا نشد');return w;}
async function assertCurrencyEnabled(currency,t){
  if(currency==='IRR')return;
  const setting=await FinanceSetting.findByPk(1,{transaction:t});
  let enabled=setting?.enabledCurrencies;
  for(let attempt=0;attempt<5&&typeof enabled==='string';attempt++){try{enabled=JSON.parse(enabled)}catch{enabled=null;break}}
  if(!Array.isArray(enabled))enabled=['USD','EUR','AED'];
  if(!enabled.includes(currency))throw ErrorApi.badRequest('ارز انتخاب‌شده در تنظیمات مالی غیرفعال است');
}
async function getBalance(pid,wid,t){let b=await StockBalance.findOne({where:{product_id:pid,warehouse_id:wid},transaction:t,lock:t.LOCK.UPDATE});if(!b)b=await StockBalance.create({product_id:pid,warehouse_id:wid,quantity:0,reorder_point:null},{transaction:t});return b;}
function totalsByProduct(items){const m=new Map();for(const x of items)m.set(x.product_id,(m.get(x.product_id)||0n)+milli(x.quantity));return m;}
async function reservedQty(parentId,type,t,excludeId){const fk=type.endsWith('RETURN')?'related_document_id':'order_document_id',where={[fk]:parentId,document_type:type,status:{[Op.in]:[INVOICE_STATUS.PENDING_APPROVAL,INVOICE_STATUS.APPROVED]}};if(excludeId)where.id={[Op.ne]:excludeId};const docs=await repo.CommercialDocument.findAll({where,include:[{model:repo.CommercialDocumentItem,as:'items'}],transaction:t,lock:t.LOCK.UPDATE});const m=new Map();for(const d of docs)for(const i of d.items)m.set(i.product_id,(m.get(i.product_id)||0n)+milli(i.quantity));return m;}
function ensureLinesWithin(requested,source,reserved,message){const available=totalsByProduct(source);for(const x of requested){const remaining=(available.get(x.productId)||0n)-(reserved.get(x.productId)||0n),q=milli(x.quantity);if(remaining<0n||q>remaining)throw ErrorApi.conflict(message,{productId:x.productId,remaining:decimal(remaining>0n?remaining:0n)});}}
async function purchaseReturnAvailability(partnerId,t,excludeReturnId){const invoices=await repo.CommercialDocument.findAll({where:{document_type:'PURCHASE_INVOICE',status:INVOICE_STATUS.APPROVED,partner_id:partnerId},include:[{model:repo.CommercialDocumentItem,as:'items',include:[{model:repo.Product,as:'product',attributes:['id','code','name','unit','tax_type']}]}],order:[['created_at','DESC']],transaction:t});const availability=new Map();for(const invoice of invoices)for(const line of invoice.items){let entry=availability.get(line.product_id);if(!entry){entry={product_id:line.product_id,product:line.product?plain(line.product):null,purchased:0n,returned:0n,last_quantity:String(line.quantity),last_unit_price:String(line.unit_price),last_discount_percent:String(line.discount_percent||0),last_discount_amount:String(BigInt(line.discount_amount||0)+BigInt(line.document_discount_amount||0)),last_tax_percent:String(line.tax_percent||0)};availability.set(line.product_id,entry);}entry.purchased+=milli(line.quantity);}const returns=await repo.CommercialDocument.findAll({where:{document_type:'PURCHASE_RETURN',partner_id:partnerId,status:{[Op.in]:[INVOICE_STATUS.PENDING_APPROVAL,INVOICE_STATUS.APPROVED]},...(excludeReturnId?{id:{[Op.ne]:excludeReturnId}}:{})},include:[{model:repo.CommercialDocumentItem,as:'items'}],transaction:t});for(const doc of returns)for(const line of doc.items){const entry=availability.get(line.product_id);if(entry)entry.returned+=milli(line.quantity);}return availability;}
async function salesReturnAvailability(partnerId,t,excludeReturnId){const invoices=await repo.CommercialDocument.findAll({where:{document_type:'SALES_INVOICE',status:INVOICE_STATUS.APPROVED,partner_id:partnerId},include:[{model:repo.CommercialDocumentItem,as:'items',include:[{model:repo.Product,as:'product',attributes:['id','code','name','unit','tax_type']}]}],order:[['created_at','DESC']],transaction:t});const availability=new Map();for(const invoice of invoices)for(const line of invoice.items){let entry=availability.get(line.product_id);if(!entry){entry={product_id:line.product_id,product:line.product?plain(line.product):null,sold:0n,returned:0n,sales:[]};availability.set(line.product_id,entry);}entry.sold+=milli(line.quantity);entry.sales.push({document_id:invoice.id,document_no:invoice.document_no,date:invoice.created_at,quantity:String(line.quantity),unit_price:String(line.unit_price),discount_percent:String(line.discount_percent||0),discount_amount:String(BigInt(line.discount_amount||0)+BigInt(line.document_discount_amount||0)),tax_percent:String(line.tax_percent||0),tax_amount:String(line.tax_amount||0),line_total:String(line.line_total)});}const returns=await repo.CommercialDocument.findAll({where:{document_type:'SALES_RETURN',partner_id:partnerId,status:{[Op.in]:[INVOICE_STATUS.PENDING_APPROVAL,INVOICE_STATUS.APPROVED]},...(excludeReturnId?{id:{[Op.ne]:excludeReturnId}}:{})},include:[{model:repo.CommercialDocumentItem,as:'items'}],transaction:t});for(const doc of returns)for(const line of doc.items){const entry=availability.get(line.product_id);if(entry)entry.returned+=milli(line.quantity);}return availability;}
function ensurePartnerSalesReturnLines(items,availability){for(const item of items){const entry=availability.get(item.productId),remaining=entry?entry.sold-entry.returned:0n,requested=milli(item.quantity);if(!entry)throw ErrorApi.badRequest('این کالا به مشتری انتخاب‌شده فروخته نشده است',{productId:item.productId});if(remaining<=0n||requested>remaining)throw ErrorApi.conflict('مقدار برگشتی از مقدار فروخته‌شده و برگشت‌نشده بیشتر است',{productId:item.productId,remaining:decimal(remaining>0n?remaining:0n)});}}
