async function orderForInvoice(type,d,t){if(!d.orderId)return null;const o=await lockDoc(d.orderId,t),expected=type==='PURCHASE_INVOICE'?'PURCHASE_ORDER':'SALES_ORDER';if(!o||o.document_type!==expected||o.status!=='OPEN')throw ErrorApi.conflict('فاکتور باید به سفارش باز از همان نوع متصل شود');if(o.partner_id!==d.partnerId)throw ErrorApi.badRequest('طرف‌حساب فاکتور با سفارش مطابقت ندارد');if((d.currency||'IRR')!==o.currency)throw ErrorApi.badRequest('ارز فاکتور باید با ارز سفارش یکسان باشد');const lines=await repo.CommercialDocumentItem.findAll({where:{document_id:o.id},transaction:t});const reserved=await reservedQty(o.id,type,t);ensureLinesWithin(d.items,lines,reserved,'مقدار فاکتور از مقدار باقی‌مانده سفارش بیشتر است');return o;}
