async function financialSummary(doc,t){if(!invoiceTypes.includes(doc.document_type))return null;const settlements=await repo.CommercialSettlement.findAll({where:{document_id:doc.id},transaction:t,attributes:['amount','direction']});const directAllocations=await DirectPartnerSettlementAllocation.findAll({where:{document_id:doc.id},transaction:t,attributes:['amount','direction']});const originalDirection=doc.document_type==='PURCHASE_INVOICE'?'OUT':'IN';const paid=[...settlements,...directAllocations].reduce((n,x)=>n+(x.direction===originalDirection?BigInt(x.amount):-BigInt(x.amount)),0n),returnType=doc.document_type==='PURCHASE_INVOICE'?'PURCHASE_RETURN':'SALES_RETURN';const returns=await repo.CommercialDocument.findAll({where:{related_document_id:doc.id,document_type:returnType,status:INVOICE_STATUS.APPROVED},include:[{model:repo.CommercialDocumentItem,as:'items',attributes:['line_total']}],transaction:t});let returned=0n;for(const r of returns)for(const i of r.items)returned+=BigInt(i.line_total);const rawNet=BigInt(doc.total_amount)-returned,net=rawNet>0n?rawNet:0n,due=net>paid?net-paid:0n,credit=paid>net?paid-net:0n;const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),dueDate=doc.due_date?String(doc.due_date).slice(0,10):null,overdueDays=due>0n&&dueDate&&dueDate<today?Math.floor((Date.parse(`${today}T00:00:00Z`)-Date.parse(`${dueDate}T00:00:00Z`))/86400000):0;return{currency:'IRR',document_currency:doc.currency||'IRR',exchange_rate:String(doc.exchange_rate||1),due_date:dueDate,due_status:!dueDate?'NO_DUE_DATE':due===0n?'SETTLED':overdueDays>0?'OVERDUE':dueDate===today?'DUE_TODAY':'NOT_DUE',overdue_days:overdueDays,invoice_amount:String(doc.total_amount),approved_returns:String(returned),net_amount:String(net),paid_amount:String(paid),balance_due:String(due),credit_balance:String(credit),payment_status:credit>0n?'CREDIT':due===0n?'PAID':paid>0n?'PARTIAL':'UNPAID'};}
async function getFinancialSummaryForAllocation(doc,t){return financialSummary(doc,t);}
async function serialize(id,type,t){const doc=await repo.findById(id,{transaction:t});if(!doc)throw ErrorApi.notFound('سند پیدا نشد');const out=plain(doc);if(type&&out.document_type!==type)throw ErrorApi.notFound('سند پیدا نشد');const f=await financialSummary(doc,t);if(f)out.financial=f;return out;}
async function approve(id, decision, userId, rejectionReason) {
  return sequelize.transaction({ isolationLevel: Transaction.ISOLATION_LEVELS.READ_COMMITTED }, async (t) => {
    const snapshot = await repo.CommercialDocument.findByPk(id, { transaction: t });
    if (!snapshot) throw ErrorApi.notFound('سند بازرگانی پیدا نشد');
    const isReturn = snapshot.document_type.endsWith('RETURN');
    const isSalesReturn = snapshot.document_type === 'SALES_RETURN';
    const source = null;
    const doc = await lockDoc(id, t);
    if (!doc) throw ErrorApi.notFound('سند بازرگانی پیدا نشد');
    if (![...invoiceTypes, 'PURCHASE_RETURN', 'SALES_RETURN'].includes(doc.document_type)) throw ErrorApi.badRequest('این نوع سند گردش تأیید ندارد');
    assertPendingApproval(doc);
    if (doc.document_type === 'SALES_RETURN') await lockPartner(doc.partner_id, 'SALES_RETURN', t);
    if (doc.document_type === 'SALES_INVOICE') await lockPartner(doc.partner_id, 'SALES_INVOICE', t);
    const lines = await repo.CommercialDocumentItem.findAll({ where: { document_id: id }, order: [['product_id', 'ASC']], transaction: t });
    // Invoice approval makes quantity sold; return transitions reserve/release it. Both paths use the same
    // customer+product row mutex before reading or changing an approved sales/return quantity.
    if (['SALES_RETURN','SALES_INVOICE'].includes(doc.document_type)) await lockSalesReturnProducts(doc.partner_id,lines,t);
    if (decision === ALLOWED_DECISIONS.REJECT) {
      await doc.update({ status: INVOICE_STATUS.REJECTED, reviewed_by: userId, reviewed_at: new Date(), rejection_reason: rejectionReason }, { transaction: t });
      return serialize(id, doc.document_type, t);
    }
    if (isSalesReturn) {
      ensurePartnerSalesReturnLines(lines.map((line) => ({ productId: line.product_id, quantity: line.quantity })), await salesReturnAvailability(doc.partner_id, t, doc.id));
    } else if (doc.document_type === 'PURCHASE_RETURN') {
      await lockPartner(doc.partner_id, 'PURCHASE_RETURN', t);
      ensurePartnerPurchaseReturnLines(lines.map((line) => ({ productId: line.product_id, quantity: line.quantity })), await purchaseReturnAvailability(doc.partner_id, t, doc.id));
    }
    await lockProducts(lines.map((line) => ({ productId: line.product_id })), t);
    const warehouse = await lockWarehouse(doc.warehouse_id, t);
    let costTotal = 0n;
    for (const line of lines) {
      const balance = await getBalance(line.product_id, warehouse.id, t);
      const before = milli(balance.quantity);
      const quantity = milli(line.quantity);
      const isInbound = doc.document_type === 'PURCHASE_INVOICE' || doc.document_type === 'SALES_RETURN';
      if (!isInbound && before < quantity) throw ErrorApi.conflict('موجودی کافی نیست؛ تأیید این سند باعث منفی‌شدن موجودی می‌شود', { productId: line.product_id, available: decimal(before), requested: decimal(quantity) });
      let unitCost = BigInt(balance.avg_unit_cost || 0);
      let nextAverageCost = unitCost;
      if (doc.document_type === 'PURCHASE_INVOICE') {
        const oldValue = roundedRial(before, unitCost);
        const incomingValue = BigInt(line.net_amount || line.line_total) + BigInt(line.allocated_freight_amount || 0);
        const afterQty = before + quantity;
        nextAverageCost = afterQty > 0n ? ((oldValue + incomingValue) * 1000n + afterQty / 2n) / afterQty : 0n;
        costTotal += incomingValue;
        await line.update({ cost_unit: String(nextAverageCost) }, { transaction: t });
      } else if (doc.document_type === 'SALES_RETURN') {
        unitCost = BigInt(balance.avg_unit_cost || 0);
        const returnCost = roundedRial(quantity, unitCost);
        costTotal += returnCost;
        const afterQty = before + quantity;
        const oldValue = roundedRial(before, BigInt(balance.avg_unit_cost || 0));
        nextAverageCost = afterQty > 0n ? ((oldValue + returnCost) * 1000n + afterQty / 2n) / afterQty : unitCost;
      } else {
        const lineCost = roundedRial(quantity, unitCost);
        costTotal += lineCost;
        if (doc.document_type === 'SALES_INVOICE') await line.update({ cost_unit: String(unitCost) }, { transaction: t });
      }
      const after = isInbound ? before + quantity : before - quantity;
      await balance.update({ quantity: decimal(after), avg_unit_cost: String(nextAverageCost) }, { transaction: t });
      await StockMovement.create({ warehouse_id: warehouse.id, product_id: line.product_id, movement_type: isInbound ? 'IN' : 'OUT', quantity: decimal(quantity), quantity_before: decimal(before), quantity_after: decimal(after), reference: doc.document_no, note: doc.note, created_by: userId, source_type: 'COMMERCIAL_DOCUMENT', source_id: doc.id }, { transaction: t });
    }
    const total = BigInt(doc.total_amount);
    let journalLines;
    if (doc.document_type === 'PURCHASE_INVOICE') {
      const inventoryValue = lines.reduce((sum, line) => sum + BigInt(line.net_amount || line.line_total), 0n) + BigInt(doc.freight_amount || 0);
      const inputTax = BigInt(doc.tax_amount || 0);
      const rounding = BigInt(doc.rounding_amount || 0);
      journalLines = [];
      if (inventoryValue > 0n) journalLines.push({ accountCode: '1200', debit: inventoryValue.toString(), credit: '0' });
      if (inputTax > 0n) journalLines.push({ accountCode: '1300', debit: inputTax.toString(), credit: '0' });
      if (rounding > 0n) journalLines.push({ accountCode: '5300', debit: rounding.toString(), credit: '0' });
      if (rounding < 0n) journalLines.push({ accountCode: '5300', debit: '0', credit: (-rounding).toString() });
      if (total > 0n) journalLines.push({ accountCode: '2000', debit: '0', credit: total.toString(), partnerId: doc.partner_id });
    } else if (doc.document_type === 'SALES_INVOICE') {
      const outputTax = BigInt(doc.tax_amount || 0);
      const revenue = total - outputTax;
      journalLines = [{ accountCode: '1100', debit: total.toString(), credit: '0', partnerId: doc.partner_id }, { accountCode: '4000', debit: '0', credit: revenue.toString() }];
      if (outputTax > 0n) journalLines.push({ accountCode: '2100', debit: '0', credit: outputTax.toString(), partnerId: doc.partner_id });
      if (costTotal > 0n) journalLines.push({ accountCode: '5000', debit: costTotal.toString(), credit: '0' }, { accountCode: '1200', debit: '0', credit: costTotal.toString() });
    } else if (doc.document_type === 'PURCHASE_RETURN') {
      journalLines = [{ accountCode: '2000', debit: total.toString(), credit: '0', partnerId: doc.partner_id }];
      if (costTotal > 0n) journalLines.push({ accountCode: '1200', debit: '0', credit: costTotal.toString() });
      const returnedTax = BigInt(doc.tax_amount || 0);
      if (returnedTax > 0n) journalLines.push({ accountCode: '1300', debit: '0', credit: returnedTax.toString() });
      const netReturn = total - returnedTax;
      if (netReturn > costTotal) journalLines.push({ accountCode: '5100', debit: '0', credit: (netReturn - costTotal).toString() });
      else if (costTotal > netReturn) journalLines.push({ accountCode: '5100', debit: (costTotal - netReturn).toString(), credit: '0' });
    } else {
      const returnedTax = BigInt(doc.tax_amount || 0);
      journalLines = [{ accountCode: '4010', debit: (total - returnedTax).toString(), credit: '0' }, { accountCode: '1100', debit: '0', credit: total.toString(), partnerId: doc.partner_id }];
      if (returnedTax > 0n) journalLines.push({ accountCode: '2100', debit: returnedTax.toString(), credit: '0', partnerId: doc.partner_id });
      if (costTotal > 0n) journalLines.push({ accountCode: '1200', debit: costTotal.toString(), credit: '0' }, { accountCode: '5000', debit: '0', credit: costTotal.toString() });
    }
    journalLines = journalLines.filter((line) => BigInt(line.debit || '0') + BigInt(line.credit || '0') > 0n);
    if (journalLines.length >= 2) await ledger.createPostedEntry({ sourceType: 'COMMERCIAL_DOCUMENT', sourceId: doc.id, entryDate: new Date().toISOString().slice(0, 10), description: `${doc.document_no} - تأیید سند بازرگانی`, createdBy: userId, lines: journalLines, transaction: t });
    await doc.update({ status: INVOICE_STATUS.APPROVED, reviewed_by: userId, reviewed_at: new Date(), rejection_reason: null }, { transaction: t });
    return serialize(id, doc.document_type, t);
  });
}async function assertOrderAvailable(doc,type,t){if(!doc||doc.document_type!==type)throw ErrorApi.notFound('سفارش پیدا نشد');if(doc.status!=='OPEN')throw ErrorApi.conflict('فقط سفارش باز قابل ویرایش یا لغو است');const invoiceType=type==='PURCHASE_ORDER'?'PURCHASE_INVOICE':'SALES_INVOICE',count=await repo.CommercialDocument.count({where:{order_document_id:doc.id,document_type:invoiceType,status:{[Op.in]:[INVOICE_STATUS.PENDING_APPROVAL,INVOICE_STATUS.APPROVED]}},transaction:t});if(count)throw ErrorApi.conflict('سفارشی که فاکتور فعال دارد قابل ویرایش یا لغو نیست');}
